ALTER TABLE "files" DROP CONSTRAINT "files_fulfillment_metadata_valid";--> statement-breakpoint
ALTER TABLE "files" ADD CONSTRAINT "files_fulfillment_metadata_valid" CHECK ("files"."file_type"::text NOT IN ('ORDER_FULFILLMENT_IMAGE','ORDER_FULFILLMENT_VIDEO') OR ("files"."visibility" = 'PRIVATE' AND ("files"."file_type"::text = 'ORDER_FULFILLMENT_IMAGE' AND "files"."mime_type" IN ('image/jpeg','image/png','image/webp') OR "files"."file_type"::text = 'ORDER_FULFILLMENT_VIDEO' AND "files"."mime_type" = 'video/mp4' AND ("files"."upload_status" <> 'VERIFIED' OR ("files"."duration_ms" IS NOT NULL AND "files"."duration_ms" > 0)))));